insert into public.study_materials select * from jsonb_populate_recordset(null::public.study_materials, $materials$[{"id":"556807f9-7dda-4ff7-942e-f83e76c7b47c","quiz":[{"a":false,"q":"Se o texto informa que o tempo médio caiu, é possível concluir automaticamente que todos os atendimentos individuais ficaram mais rápidos.","why":"A média não descreve necessariamente cada caso individual; a alternativa extrapola o dado."},{"a":true,"q":"O conectivo “embora” costuma introduzir relação de concessão.","why":"Concessão apresenta fato que poderia contrariar a ideia principal, mas não a impede."},{"a":false,"q":"Na reescrita, substituir “pode” por “deve” preserva sempre o sentido original.","why":"“Pode” indica possibilidade; “deve” pode indicar obrigação ou probabilidade. A modalidade muda."},{"a":true,"q":"A oração adjetiva restritiva delimita o grupo a que o substantivo se refere.","why":"Ela restringe o alcance do antecedente, diferentemente da explicativa."},{"a":true,"q":"Inferência textual é uma conclusão sustentada por pistas do texto, e não uma opinião livre do leitor.","why":"A inferência deve decorrer logicamente das informações apresentadas."}],"slug":"pcac-2026-portugues-interpretacao-inferencia-coesao-reescrita","title":"Interpretação de textos: inferência, coesão e reescrita sem mudar o sentido","body_md":"# Interpretação de textos: inferência, coesão e reescrita\n\n> **QUESTÃO DE ABERTURA — padrão IDECAN (autoral)**\n>\n> Leia: “A análise de dados não substitui o trabalho investigativo; ela organiza indícios, aponta relações e ajuda a definir diligências.” A partir do trecho, é correto concluir que a análise de dados:\n>\n> **Resposta:** auxilia e orienta a investigação, mas não a substitui. A conclusão está autorizada pelo texto. Não se pode afirmar que a análise decide sozinha a autoria ou dispensa diligências.\n>\n> **Como resolver:** diferencie informação expressa, inferência autorizada e extrapolação. A alternativa correta deve ser sustentada pelo texto, não por uma opinião pessoal.\n\n## 1. Leitura em três passagens\n1. **Panorama:** identifique gênero, tema e situação comunicativa.\n2. **Estrutura:** localize tese, argumentos, exemplos, ressalvas e conclusão.\n3. **Precisão:** retorne ao trecho que sustenta cada alternativa e confira palavras absolutas como “sempre”, “nunca”, “somente” e “necessariamente”.\n\nTextos argumentativos defendem uma tese; textos normativos estabelecem regras; textos científicos expõem método, dados e conclusões; textos jornalísticos informam e contextualizam fatos. O gênero altera a finalidade, mas não elimina a necessidade de leitura literal e inferencial.\n\n## 2. Ideia principal e inferência\nA ideia principal resume o núcleo do texto. Inferir é concluir algo que não está escrito literalmente, mas decorre de pistas textuais. Extrapolar é acrescentar informação que o texto não autoriza.\n\n**Exemplo:** “Após a implantação do protocolo, o tempo médio de atendimento caiu de 40 para 25 minutos.” É possível inferir que houve redução do tempo médio. Não é possível concluir, sem outros dados, que todos os atendimentos ficaram mais rápidos ou que a satisfação aumentou.\n\n## 3. Coesão: quem retoma quem?\nCoesão é a ligação formal entre partes do texto. Pronomes e expressões referenciais retomam ou antecipam elementos:\n- “O relatório foi concluído. **Ele** será encaminhado.” — “ele” retoma relatório.\n- “A equipe analisou os dados e, **por isso**, adiou a conclusão.” — conectivo expressa consequência.\n- “**Embora** houvesse divergências, a equipe concluiu o relatório.” — concessão.\n\nNa prova, substitua mentalmente o pronome pelo referente. Se a frase ficar incoerente, você escolheu o antecedente errado.\n\n## 4. Conectivos mudam a lógica\n| Relação | Conectivos comuns |\n|---|---|\n| Causa | porque, visto que, uma vez que |\n| Consequência/conclusão | portanto, por isso, logo |\n| Oposição | mas, porém, contudo |\n| Concessão | embora, ainda que, mesmo que |\n| Condição | se, caso, desde que |\n| Finalidade | para que, a fim de que |\n| Adição | além disso, também |\n| Explicação | pois, porque |\n\nCuidado: “porque” pode introduzir causa ou explicação; o contexto decide. “Embora” não equivale a “porque”: a primeira ideia é concessiva, a segunda causal/explicativa.\n\n## 5. Reescrita e equivalência\nUma reescrita é equivalente quando preserva o sentido essencial, a relação lógica, o tempo, a modalidade e os referentes. Trocar “pode” por “deve” altera possibilidade para obrigação. Trocar “alguns” por “todos” amplia indevidamente o alcance.\n\n**Paralelismo:** elementos coordenados devem manter estrutura equivalente. “A equipe precisa coletar, preservar e analisar os vestígios” mantém os três verbos no infinitivo. “A equipe precisa coletar, preservação e analisar” quebra o paralelismo.\n\n## 6. Pontuação e sentido\nA vírgula pode separar explicações, deslocamentos e orações; não deve separar sujeito e verbo nem verbo e complemento sem justificativa sintática. Orações adjetivas explicativas e restritivas podem alterar o alcance:\n- “Os servidores, que concluíram o curso, foram promovidos.” — explicativa: o texto sugere que todos concluíram.\n- “Os servidores que concluíram o curso foram promovidos.” — restritiva: apenas o grupo especificado.\n\n## 7. Técnica de prova\n- Leia o comando antes das alternativas: “depreende-se”, “infere-se”, “mantém o sentido”.\n- Marque a tese em uma frase curta.\n- Para cada alternativa, procure evidência textual.\n- Em reescrita, compare conectivo, negação, quantificador, tempo verbal e modalizador.\n- Elimine alternativas que adicionam causa, intenção ou consequência não mencionada.\n\n## 8. Pegadinhas\n1. Confundir opinião do candidato com inferência textual.\n2. Trocar “pode” por “deve”.\n3. Transformar “alguns” em “todos”.\n4. Trocar concessão por causa.\n5. Atribuir pronome ao antecedente mais próximo sem verificar sentido.\n6. Ignorar que pontuação pode alterar o alcance da oração.\n\n## 9. Fontes e alinhamento\nAnexo III do Edital PC-AC 2026: leitura, compreensão, interpretação, análise crítica e inferencial; estruturação de parágrafos; articulação textual; coesão, coerência e reescrita. Conteúdo autoral, não questão oficial.","summary":"Método de leitura ativa, identificação de tese, inferências, referentes, conectivos e equivalência de reescrita.","created_at":"2026-11-21T10:31:09.466287+00:00","discipline":"Língua Portuguesa","flashcards":[{"b":"Conclusão não expressa literalmente, mas sustentada pelas pistas e relações do texto.","f":"O que é inferência textual?"},{"b":"Acrescentar informação que o texto não autoriza concluir.","f":"O que é extrapolação?"},{"b":"Concessão.","f":"Que relação o conectivo “embora” expressa?"},{"b":"Sentido, conectivos, negação, quantificadores, tempo verbal, modalidade e referentes.","f":"O que verificar na reescrita?"},{"b":"A restritiva delimita o referente; a explicativa acrescenta informação sobre ele.","f":"Qual a diferença entre oração restritiva e explicativa?"}],"sort_order":90,"updated_at":"2026-11-21T10:31:09.466287+00:00","legal_basis":[],"reviewed_at":null,"reviewed_by":null,"source_note":"Conteúdo complementar autoral alinhado ao Anexo III do Edital nº 001 SEAD/PCAC, de 05/11/2026; recorte até 06/11/2026.","topic_label":"Interpretação, inferência, coesão e reescrita","contest_name":"PC-AC 2026","legal_review":null,"content_status":"active","practice_review":null,"syllabus_topic_order":1,"law_version_checked_at":null},{"id":"dc4eb716-fbd3-4235-bfd2-ffedf061c693","quiz":[{"a":true,"q":"A condicional P → Q é falsa somente quando P é verdadeira e Q é falsa.","why":"Essa é a única linha falsa da tabela-verdade da condicional."},{"a":false,"q":"A negação de “P e Q” é “não P e não Q”.","why":"Pela lei de De Morgan, a negação é “não P ou não Q”."},{"a":true,"q":"A contrapositiva de “Se P, então Q” é “Se não Q, então não P”.","why":"A contrapositiva é logicamente equivalente à condicional original."},{"a":false,"q":"A recíproca de P → Q, isto é, Q → P, é sempre equivalente à proposição original.","why":"A recíproca não é equivalente em geral."},{"a":true,"q":"A negação de “todos os relatórios foram revisados” é “pelo menos um relatório não foi revisado”.","why":"Negar universal exige apresentar ao menos um contraexemplo."}],"slug":"pcac-2026-raciocinio-logico-proposicoes-negacao-equivalencias","title":"Lógica proposicional: conectivos, negação e equivalências sem decorar fórmulas","body_md":"# Lógica proposicional: conectivos, negação e equivalências\n\n> **QUESTÃO DE ABERTURA — padrão IDECAN (autoral)**\n>\n> Considere: “Se o vestígio foi preservado, então poderá ser periciado”. Qual é a negação lógica dessa proposição?\n>\n> **Resposta:** “O vestígio foi preservado e não poderá ser periciado.”\n>\n> **Como resolver:** a negação de “Se P, então Q” é “P e não Q”. Não negue as duas partes ao mesmo tempo.\n\n## 1. O que é proposição?\nÉ uma frase declarativa à qual se pode atribuir valor verdadeiro (V) ou falso (F), mas não ambos simultaneamente. “O laudo foi juntado aos autos” é proposição. “Junte o laudo!” é ordem, não proposição. Pergunta também não é proposição.\n\nProposição simples não contém conectivo lógico. Proposição composta combina proposições por conectivos.\n\n## 2. Conectivos essenciais\n- **Conjunção (P e Q):** verdadeira somente quando ambas são verdadeiras.\n- **Disjunção inclusiva (P ou Q):** falsa somente quando ambas são falsas; admite que as duas sejam verdadeiras.\n- **Condicional (se P, então Q):** falsa somente quando P é verdadeira e Q é falsa.\n- **Bicondicional (P se e somente se Q):** verdadeira quando P e Q têm o mesmo valor lógico.\n\nTabela da condicional:\n| P | Q | P → Q |\n|---|---|---|\n| V | V | V |\n| V | F | F |\n| F | V | V |\n| F | F | V |\n\nMacete: a condicional só falha quando a promessa “se P, então Q” é quebrada: P acontece e Q não.\n\n## 3. Negação sem erro\n- Negação de P: não P.\n- Negação de “P e Q”: não P ou não Q.\n- Negação de “P ou Q”: não P e não Q.\n- Negação de “Se P, então Q”: P e não Q.\n- Negação de “P se e somente se Q”: (P e não Q) ou (não P e Q).\n\n**Exemplo cotidiano:** “O sistema está ligado e conectado”. Negar não é “está desligado e desconectado”; basta que pelo menos uma parte falhe: “não está ligado ou não está conectado”.\n\n## 4. Equivalências importantes\n- P → Q equivale a não P ou Q.\n- P → Q equivale à contrapositiva: não Q → não P.\n- Dupla negação: não (não P) equivale a P.\n- Leis de De Morgan: negue cada parte e troque “e” por “ou”, ou vice-versa.\n\nA recíproca Q → P não é equivalente à condicional P → Q. A inversa não P → não Q também não é equivalente em geral. A contrapositiva, sim.\n\n## 5. Como resolver\n1. Separe as proposições simples e atribua letras.\n2. Identifique o conectivo principal (o que liga os blocos maiores).\n3. Se pedirem negação, negue a estrutura inteira e aplique a regra correspondente.\n4. Se pedirem equivalência, procure contrapositiva ou eliminação da condicional.\n5. Confira com um caso que torne a frase falsa: isso evita decorar regra errada.\n\n## 6. Pegadinhas\n- “Ou” lógico geralmente é inclusivo, salvo indicação de exclusividade.\n- Condicional não é falsa quando o antecedente é falso.\n- Negar “todo” gera “existe pelo menos um que não”.\n- Negar “algum” gera “nenhum”.\n- Recíproca não é contrapositiva.\n- Em “somente se”, a direção da condicional costuma inverter em relação à leitura intuitiva.\n\n## 7. Quantificadores\n- “Todos os relatórios foram revisados” → negação: “Pelo menos um relatório não foi revisado”.\n- “Algum relatório foi revisado” → negação: “Nenhum relatório foi revisado”.\n- “Nenhum relatório foi revisado” → negação: “Pelo menos um foi revisado”.\n\n## 8. Fontes e alinhamento\nAnexo III do Edital PC-AC 2026: estruturas lógicas, proposições simples e compostas, conectivos, tabelas-verdade, equivalências, negação e validade de argumentos. Questões deste módulo são autorais no padrão da banca.","summary":"Aprenda a identificar proposições, traduzir frases, negar corretamente e reconhecer equivalências em questões.","created_at":"2026-11-21T10:31:09.466287+00:00","discipline":"Raciocínio Lógico","flashcards":[{"b":"Somente quando P é verdadeira e Q é falsa.","f":"Quando a condicional P → Q é falsa?"},{"b":"Não P ou não Q.","f":"Qual a negação de P e Q?"},{"b":"Não Q → não P.","f":"Qual a contrapositiva de P → Q?"},{"b":"Não, em geral.","f":"A recíproca Q → P é equivalente a P → Q?"},{"b":"“Existe pelo menos um que não é”.","f":"Qual a negação de “todos são”?"}],"sort_order":90,"updated_at":"2026-11-21T10:31:09.466287+00:00","legal_basis":[],"reviewed_at":null,"reviewed_by":null,"source_note":"Conteúdo complementar autoral alinhado ao Anexo III do Edital nº 001 SEAD/PCAC, de 05/11/2026; recorte até 06/11/2026.","topic_label":"Proposições, conectivos, negação e equivalências","contest_name":"PC-AC 2026","legal_review":null,"content_status":"active","practice_review":null,"syllabus_topic_order":1,"law_version_checked_at":null}]$materials$::jsonb) on conflict (slug) do nothing;
insert into public.curated_question_catalog select * from jsonb_populate_recordset(null::public.curated_question_catalog, $questions$[{"id":"a4209cc2-375e-4804-94f4-eb4d98ef5e14","state":"AC","subject":"Língua Portuguesa","subtopic":"Inferência e extrapolação","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:31:09.466287+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"O enunciado informa apenas uma média. Não autoriza generalizar para todas as unidades nem atribuir causalidade sem evidências adicionais.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:31:09.466287+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Inferência e extrapolação","question_text":"Um relatório afirma: “O número médio de ocorrências registradas caiu no trimestre”. Sem outros dados, conclui-se corretamente que:\n\nA) todas as unidades tiveram redução.\nB) cada tipo de ocorrência diminuiu.\nC) o total de ocorrências caiu em todos os municípios.\nD) houve redução do indicador médio informado, sem que isso prove redução em cada unidade.\nE) a política pública foi necessariamente a causa da redução.","content_status":"active","career_category":"conhecimentos básicos","official_answer":"D","external_item_key":"pcac-port-inferencia-01","import_unique_key":"aa497a1b8d289b2ee0612ca49e26b6be3764156c903337ca7d99ed86d944ecdd","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"aa497a1b8d289b2ee0612ca49e26b6be3764156c903337ca7d99ed86d944ecdd","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"9cd1dfa9-8430-4846-bd4f-2e89a6692581","state":"AC","subject":"Língua Portuguesa","subtopic":"Reescrita e equivalência","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:31:09.466287+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"Poderá expressa possibilidade; deverá pode indicar obrigação ou expectativa. A modalidade é parte do sentido e precisa ser preservada.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:31:09.466287+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Reescrita e equivalência","question_text":"Na frase “A equipe poderá concluir o relatório amanhã”, a substituição de “poderá” por “deverá”:\n\nA) preserva necessariamente o sentido.\nB) transforma possibilidade em obrigação ou expectativa mais forte, alterando a modalidade.\nC) altera apenas a pessoa verbal.\nD) transforma voz ativa em passiva.\nE) não produz qualquer mudança semântica.","content_status":"active","career_category":"conhecimentos básicos","official_answer":"B","external_item_key":"pcac-port-reescrita-01","import_unique_key":"ae55ce7357124a0dadfe050a191dac5a7bf3f3cc7d31eb161bb1cddb778754d4","syllabus_topic_id":"4a545820-c8db-449d-b9d2-29009a5f32de","import_content_key":"ae55ce7357124a0dadfe050a191dac5a7bf3f3cc7d31eb161bb1cddb778754d4","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"4e1454b3-f786-4aef-b1f5-4f80bd3a48c7","state":"AC","subject":"Raciocínio Lógico","subtopic":"Negação de condicional","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:31:09.466287+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A negação de P → Q é P e não Q. Mantém-se o antecedente e nega-se o consequente, ligados por conjunção.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:31:09.466287+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Negação de condicional","question_text":"A negação lógica de “Se o vestígio foi preservado, então poderá ser periciado” é:\n\nA) O vestígio não foi preservado e poderá ser periciado.\nB) O vestígio foi preservado e não poderá ser periciado.\nC) O vestígio não foi preservado ou poderá ser periciado.\nD) O vestígio foi preservado ou não poderá ser periciado.\nE) O vestígio não foi preservado e não poderá ser periciado.","content_status":"active","career_category":"conhecimentos básicos","official_answer":"B","external_item_key":"pcac-rl-condicional-01","import_unique_key":"c7dd328d31913388e5eff594e6fd0ba9ae5d015eee59a44bfe1e419bddd2c2d6","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"c7dd328d31913388e5eff594e6fd0ba9ae5d015eee59a44bfe1e419bddd2c2d6","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null},{"id":"13ec4989-e087-445a-bcd2-33d14a68c83b","state":"AC","subject":"Raciocínio Lógico","subtopic":"Negação de quantificadores","role_type":"Oficial Investigador","source_id":"ad99dcf6-2e35-4e27-836d-c5e1b8226806","created_at":"2026-11-21T10:31:09.466287+00:00","difficulty":"média","exam_board":"IDECAN","career_name":"Oficial Investigador de Polícia","explanation":"A negação de uma afirmação universal exige apenas um contraexemplo: existe ao menos um documento que não foi conferido.","is_original":true,"legal_basis":[],"verified_at":"2026-11-21T10:31:09.466287+00:00","contest_name":"PC-AC 2026","contest_year":2026,"tested_topic":"Negação de quantificadores","question_text":"A negação de “Todos os documentos foram conferidos” é:\n\nA) Nenhum documento foi conferido.\nB) Todos os documentos não foram conferidos.\nC) Pelo menos um documento não foi conferido.\nD) Alguns documentos foram conferidos.\nE) A maioria dos documentos não foi conferida.","content_status":"active","career_category":"conhecimentos básicos","official_answer":"C","external_item_key":"pcac-rl-universal-01","import_unique_key":"0300bccdff2f512efdd4da063cda4ddfa28a367cddbb03a313927783b578210e","syllabus_topic_id":"92f3abc8-e74d-4eb2-9263-23e16e39d1d5","import_content_key":"0300bccdff2f512efdd4da063cda4ddfa28a367cddbb03a313927783b578210e","didactic_provenance":{"type":"original_didactic","aligned_to":"Anexo III PC-AC 2026","opening_question":true},"law_version_checked_at":null}]$questions$::jsonb) on conflict (source_id, external_item_key) do nothing;
commit;